# ===========================================================================
# parse_developer_output
# ===========================================================================

class TestParseDeveloperOutput:

    def test_single_file_block(self):
        raw = '<file path="src/main.py">\nprint("hello")\n</file>'
        result = parse_developer_output(raw)
        assert len(result) == 1
        assert result[0].relative_path == "src/main.py"
        assert result[0].content == 'print("hello")'

    def test_multiple_file_blocks(self):
        raw = (
            '<file path="a.py">\ndef a(): pass\n</file>\n'
            '<file path="b.py">\ndef b(): pass\n</file>'
        )
        result = parse_developer_output(raw)
        assert len(result) == 2
        paths = [r.relative_path for r in result]
        assert "a.py" in paths
        assert "b.py" in paths

    def test_duplicate_paths_last_wins(self):
        raw = (
            '<file path="app.py">\nversion = 1\n</file>\n'
            "Some intermediate reasoning.\n"
            '<file path="app.py">\nversion = 2\n</file>'
        )
        result = parse_developer_output(raw)
        assert len(result) == 1
        assert result[0].content == "version = 2"

    def test_strips_whitespace_from_content(self):
        raw = '<file path="utils.py">\n\n\ndef helper(): pass\n\n\n</file>'
        result = parse_developer_output(raw)
        assert result[0].content == "def helper(): pass"

    def test_raises_on_no_file_blocks(self):
        raw = "Here is some reasoning but no file blocks were output."
        with pytest.raises(ValueError, match="no <file> blocks"):
            parse_developer_output(raw)

    def test_raises_on_empty_string(self):
        with pytest.raises(ValueError):
            parse_developer_output("")

    def test_content_containing_triple_backticks(self):
        # This is the key advantage of XML-style delimiters over markdown fences.
        content = '```python\nprint("hello")\n```'
        raw     = f'<file path="example.py">\n{content}\n</file>'
        result  = parse_developer_output(raw)
        assert result[0].content == content.strip()

    def test_single_quotes_in_path_attribute(self):
        raw = "<file path='src/agents/planner.py'>\ndef plan(): pass\n</file>"
        result = parse_developer_output(raw)
        assert result[0].relative_path == "src/agents/planner.py"

    def test_preserves_file_order_for_non_duplicates(self):
        raw = (
            '<file path="c.py">\n# c\n</file>\n'
            '<file path="a.py">\n# a\n</file>\n'
            '<file path="b.py">\n# b\n</file>'
        )
        result = parse_developer_output(raw)
        # dict preserves insertion order — a and b are unique, c is first
        paths = [r.relative_path for r in result]
        assert paths == ["c.py", "a.py", "b.py"]

    def test_preamble_prose_is_ignored(self):
        raw = (
            "Let me think about this...\n"
            "I will write the following files:\n\n"
            '<file path="main.py">\npass\n</file>\n\n'
            "That completes the implementation."
        )
        result = parse_developer_output(raw)
        assert len(result) == 1
        assert result[0].relative_path == "main.py"

    def test_deeply_nested_path(self):
        raw = '<file path="app/workflows/codegen/nodes.py">\n# content\n</file>'
        result = parse_developer_output(raw)
        assert result[0].relative_path == "app/workflows/codegen/nodes.py"

    def test_multiline_file_content(self):
        content = "\n".join([
            "from __future__ import annotations",
            "",
            "class Foo:",
            '    """A class."""',
            "",
            "    def method(self) -> None:",
            "        pass",
        ])
        raw = f'<file path="foo.py">\n{content}\n</file>'
        result = parse_developer_output(raw)
        assert "class Foo:" in result[0].content
        assert "def method" in result[0].content


# ===========================================================================
# parse_reviewer_verdict
# ===========================================================================

class TestParseReviewerVerdict:

    def test_clean_pass_json(self):
        raw    = '{"passed": true, "feedback": "", "severity": "blocking"}'
        result = parse_reviewer_verdict(raw, "workflow_reviewer")
        assert result.passed   is True
        assert result.feedback == ""
        assert result.severity == "blocking"

    def test_clean_fail_json(self):
        raw    = '{"passed": false, "feedback": "Missing ToolNode.", "severity": "blocking"}'
        result = parse_reviewer_verdict(raw, "security_reviewer")
        assert result.passed   is False
        assert "ToolNode" in result.feedback
        assert result.severity == "blocking"

    def test_json_in_markdown_fence(self):
        raw = (
            "```json\n"
            '{"passed": true, "feedback": "looks good", "severity": "blocking"}\n'
            "```"
        )
        result = parse_reviewer_verdict(raw, "prompt_reviewer")
        assert result.passed is True

    def test_prose_before_json(self):
        raw = (
            "After reviewing the code, here is my verdict:\n\n"
            '{"passed": false, "feedback": "No input validation.", "severity": "blocking"}'
        )
        result = parse_reviewer_verdict(raw, "workflow_reviewer")
        assert result.passed   is False
        assert "input validation" in result.feedback

    def test_severity_defaults_to_blocking_when_absent(self):
        raw    = '{"passed": true, "feedback": ""}'
        result = parse_reviewer_verdict(raw, "prompt_reviewer")
        assert result.severity == "blocking"

    def test_advisory_severity_preserved(self):
        raw    = '{"passed": false, "feedback": "Minor nit.", "severity": "advisory"}'
        result = parse_reviewer_verdict(raw, "prompt_reviewer")
        assert result.severity == "advisory"
        assert result.passed   is False

    def test_invalid_json_returns_blocking_failure(self):
        raw    = "This is not JSON at all."
        result = parse_reviewer_verdict(raw, "workflow_reviewer")
        assert result.passed   is False
        assert result.severity == "blocking"
        assert "workflow_reviewer" in result.feedback

    def test_empty_string_returns_blocking_failure(self):
        result = parse_reviewer_verdict("", "security_reviewer")
        assert result.passed   is False
        assert result.severity == "blocking"

    def test_truncated_json_returns_blocking_failure(self):
        raw    = '{"passed": true, "feed'
        result = parse_reviewer_verdict(raw, "workflow_reviewer")
        assert result.passed   is False

    def test_reviewer_name_in_failure_feedback(self):
        result = parse_reviewer_verdict("not json", "my_special_reviewer")
        assert "my_special_reviewer" in result.feedback

    def test_passed_false_with_empty_feedback(self):
        raw    = '{"passed": false, "feedback": "", "severity": "blocking"}'
        result = parse_reviewer_verdict(raw, "security_reviewer")
        assert result.passed   is False
        assert result.feedback == ""


# ===========================================================================
# parse_critic_output
# ===========================================================================

class TestParseCriticOutput:

    def test_clean_pass(self):
        raw            = '{"passed": true, "issues": [], "feedback": ""}'
        passed, feedback = parse_critic_output(raw)
        assert passed   is True
        assert feedback == ""

    def test_clean_fail_with_issues(self):
        raw = (
            '{"passed": false, '
            '"issues": ["Loop is unbounded", "No docstring on tool"], '
            '"feedback": ""}'
        )
        passed, feedback = parse_critic_output(raw)
        assert passed   is False
        assert "Loop is unbounded" in feedback
        assert "No docstring on tool" in feedback

    def test_clean_fail_with_explicit_feedback(self):
        raw = (
            '{"passed": false, "issues": [], '
            '"feedback": "Planner is missing dispatch logic."}'
        )
        passed, feedback = parse_critic_output(raw)
        assert passed   is False
        assert "dispatch logic" in feedback

    def test_fail_prefers_feedback_over_issues_when_both_present(self):
        raw = (
            '{"passed": false, '
            '"issues": ["issue A"], '
            '"feedback": "Explicit consolidated feedback."}'
        )
        passed, feedback = parse_critic_output(raw)
        assert passed   is False
        # explicit feedback takes precedence
        assert "Explicit consolidated feedback" in feedback

    def test_malformed_json_returns_soft_pass(self):
        raw            = "I cannot produce a verdict right now."
        passed, feedback = parse_critic_output(raw)
        assert passed   is True
        assert feedback == ""

    def test_empty_string_returns_soft_pass(self):
        passed, feedback = parse_critic_output("")
        assert passed   is True
        assert feedback == ""

    def test_json_in_markdown_fence(self):
        raw = (
            "```json\n"
            '{"passed": false, "issues": ["Missing ToolNode"], "feedback": ""}\n'
            "```"
        )
        passed, feedback = parse_critic_output(raw)
        assert passed   is False
        assert "ToolNode" in feedback

    def test_issues_formatted_as_bullet_list_when_no_feedback(self):
        raw = (
            '{"passed": false, '
            '"issues": ["A", "B", "C"], '
            '"feedback": ""}'
        )
        passed, feedback = parse_critic_output(raw)
        assert "- A" in feedback
        assert "- B" in feedback
        assert "- C" in feedback
